export const STORAGE_KEY = 'field-notes.v1';
export const BODY_LIMIT = 5000;
export const LABEL_LIMIT = 40;

export class ConflictError extends Error {}

export function noteInput(body, label = '') {
  if (typeof body !== 'string' || !body.trim()) throw new Error('메모 내용을 입력해 주세요.');
  if (body.length > BODY_LIMIT) throw new Error(`메모는 ${BODY_LIMIT}자까지 입력할 수 있습니다.`);
  if (typeof label !== 'string' || label.length > LABEL_LIMIT) throw new Error(`분류는 ${LABEL_LIMIT}자까지 입력할 수 있습니다.`);
  return { body: body.trim(), label: label.trim() };
}

export function addNote(notes, input, id, time) {
  if (notes.some(note => note.id === id)) throw new Error('메모 번호가 겹쳤습니다. 다시 저장해 주세요.');
  return [{ ...noteInput(input.body, input.label), id, createdAt: time, updatedAt: time }, ...notes];
}

export function editNote(notes, id, input, time) {
  if (!notes.some(note => note.id === id)) throw new Error('수정할 원본이 없습니다. 내용을 복사한 뒤 새 메모로 저장해 주세요.');
  const content = noteInput(input.body, input.label);
  return notes.map(note => note.id === id ? { ...note, ...content, updatedAt: time } : note);
}

export function deleteNote(notes, id) {
  if (!notes.some(note => note.id === id)) throw new Error('삭제할 메모가 없습니다. 목록을 다시 불러와 주세요.');
  return notes.filter(note => note.id !== id);
}

const normalize = value => value.normalize('NFKC').toLocaleLowerCase('ko-KR');
export function findNotes(notes, query = '') {
  const words = normalize(query).trim().split(/\s+/).filter(Boolean);
  return notes.filter(note => {
    const text = normalize(`${note.body}\n${note.label}`);
    return words.every(word => text.includes(word));
  }).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt) || b.id.localeCompare(a.id));
}

function validTime(value) {
  return typeof value === 'string' && !Number.isNaN(Date.parse(value)) && new Date(value).toISOString() === value;
}

export function decode(raw) {
  if (raw === null) return [];
  let parsed;
  try { parsed = JSON.parse(raw); } catch { throw new Error('저장 데이터가 손상되었습니다. 원본을 덮어쓰지 않았습니다.'); }
  if (!parsed || parsed.version !== 1 || !Array.isArray(parsed.notes)) {
    throw new Error('지원하지 않는 저장 데이터입니다. 원본을 덮어쓰지 않았습니다.');
  }
  const ids = new Set();
  for (const note of parsed.notes) {
    if (!note || typeof note.id !== 'string' || !note.id || ids.has(note.id) ||
        typeof note.body !== 'string' || !note.body.trim() || note.body.length > BODY_LIMIT ||
        typeof note.label !== 'string' || note.label.length > LABEL_LIMIT ||
        !validTime(note.createdAt) || !validTime(note.updatedAt)) {
      throw new Error('저장 데이터 형식을 읽을 수 없습니다. 원본을 덮어쓰지 않았습니다.');
    }
    ids.add(note.id);
  }
  return parsed.notes;
}

// A saved baseline detects changes made by another tab before this write.
// localStorage has no cross-tab transaction; truly simultaneous writes remain a browser limit.
export function createRepository(storage) {
  let baseline;
  let loaded = false;
  return {
    load() {
      // Every load attempt must establish a valid baseline before another write.
      loaded = false;
      const raw = storage.getItem(STORAGE_KEY);
      const notes = decode(raw);
      baseline = raw;
      loaded = true;
      return notes;
    },
    save(notes) {
      if (!loaded) throw new Error('저장 데이터를 먼저 불러와 주세요.');
      const encoded = JSON.stringify({ version: 1, notes });
      decode(encoded);
      if (storage.getItem(STORAGE_KEY) !== baseline) {
        throw new ConflictError('다른 창에서 메모가 변경되었습니다. 목록을 다시 불러온 뒤 저장해 주세요. 입력 중인 내용은 남아 있습니다.');
      }
      storage.setItem(STORAGE_KEY, encoded);
      baseline = encoded;
    },
  };
}

